<?php
defined('ABSPATH') || exit;
final class Flint_Base_Integrations {
 private static $instance;
 public static function instance(){if(!self::$instance)self::$instance=new self();return self::$instance;}
 private function __construct(){ add_action('wp_head',array($this,'head'),1); add_action('wp_body_open',array($this,'body'),1); add_action('init',array($this,'login_alias'),0); add_filter('login_url',array($this,'login_url'),10,3); add_action('admin_init',array($this,'directory_indexing')); }
 public function head(){ $rows=(array)flint_base_get_setting('scripts',array()); foreach($rows as $r){$type=$r['type']??'';$v=trim($r['value']??'');if(!$v)continue; if('ga4'===$type){echo "\n<!-- Flint GA4 --><script async src=\"https://www.googletagmanager.com/gtag/js?id=".esc_attr($v)."\"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}gtag('js',new Date());gtag('config','".esc_js($v)."');</script>\n";} elseif('gtm'===$type){echo "\n<!-- Flint GTM --><script>(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':new Date().getTime(),event:'gtm.js'});var f=d.getElementsByTagName(s)[0],j=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;j.src='https://www.googletagmanager.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);})(window,document,'script','dataLayer','".esc_js($v)."');</script>\n";} elseif('maps'===$type){echo '<script async defer src="https://maps.googleapis.com/maps/api/js?key='.esc_attr($v).'"></script>';} elseif('script_url'===$type && wp_http_validate_url($v)){echo '<script src="'.esc_url($v).'"></script>';}} }
 public function body(){ foreach((array)flint_base_get_setting('scripts',array()) as $r){if(($r['type']??'')==='gtm'&&!empty($r['value']))echo '<noscript><iframe src="https://www.googletagmanager.com/ns.html?id='.esc_attr($r['value']).'" height="0" width="0" style="display:none;visibility:hidden"></iframe></noscript>';}}
 public function login_alias(){ $path=trim((string)parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH),'/'); if($path==='login'){ require ABSPATH.'wp-login.php'; exit; } if($path==='wp-login.php' && ($_SERVER['REQUEST_METHOD']??'GET')==='GET' && empty($_GET['action'])){ wp_safe_redirect(home_url('/login/')); exit; } }
 public function login_url($url,$redirect,$force){$u=home_url('/login/');if($redirect)$u=add_query_arg('redirect_to',rawurlencode($redirect),$u);return $u;}
 public function directory_indexing(){ if(!current_user_can('manage_options'))return; $file=ABSPATH.'.htaccess'; if(!file_exists($file)||!is_writable($file))return; $c=file_get_contents($file); if(strpos($c,'# BEGIN Flint Directory Protection')!==false)return; $block="\n# BEGIN Flint Directory Protection\nOptions -Indexes\n# END Flint Directory Protection\n"; @file_put_contents($file,$block.$c); }
}
